package org.marketreview.nativeapp;
import java.io.File;
import java.util.*;
import org.json.*;
final class CommentWorkshopChecks {
  interface Action{void run() throws Exception;}
  static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
  static void rejects(Action action) throws Exception {boolean denied=false;try{action.run();}catch(Exception e){denied=true;}check(denied,"invalid identity/write should be rejected");}
  static JSONObject fixture() throws Exception {
    JSONObject channel=new JSONObject().put("id",1).put("channelKey","creator-one").put("displayName","作者甲").put("profileUrl","https://www.douyin.com/user/creator");
    JSONArray comments=new JSONArray().put(new JSONObject().put("commentId","parent").put("authorName","读者").put("text","支持原文完整尾部 — 原始评论").put("likes",JSONObject.NULL))
      .put(new JSONObject().put("commentId","reply").put("parentCommentId","parent").put("authorName","作者甲").put("authorProfileUrl","https://www.douyin.com/user/creator").put("text","作者原文回复").put("observedAt","2026-10-12T12:00:00Z"))
      .put(new JSONObject().put("commentId","same-name").put("authorName","作者甲").put("authorProfileUrl","https://www.douyin.com/user/imposter").put("creatorStatus","verified").put("text","同名但不是作者"))
      .put(new JSONObject().put("commentId","platform").put("parentCommentId","absent").put("authorName","作者甲").put("isCreatorLabel",true).put("text","平台标注回复"));
    JSONObject observation=new JSONObject().put("id",2).put("externalContentId","7259684447530929443").put("sourceUrl","https://www.douyin.com/video/7259684447530929443?signature=secret").put("title","受控观察").put("content","保存的观察全文").put("transcript","识别原稿");
    return new JSONObject().put("channel",channel).put("observation",observation).put("commentData",new JSONObject().put("comments",comments).put("hasMore",true).put("total",10).put("coverage",new JSONObject().put("status","visible_partial").put("complete",true).put("visibleCount",8)));
  }
  static void model() throws Exception {
    JSONObject row=CommentWorkshopModel.normalize(fixture().toString()).getJSONObject(0);JSONArray authors=CommentWorkshopModel.comments(row,"","creator");check(authors.length()==2&&!row.getJSONObject("coverage").getBoolean("complete")&&row.getJSONArray("comments").getJSONObject(0).isNull("likes"),"creator proof/partial coverage/unknown likes");
    check(CommentWorkshopModel.comments(row,"作者原文","all").getJSONObject(0).getString("parentText").contains("完整尾部"),"full reply parent preserved");check(CommentWorkshopModel.comments(row,"平台标注","all").getJSONObject(0).getBoolean("parentMissing"),"missing parent explicit");
    JSONObject ref=CommentWorkshopModel.commentRef(row,"reply");check(CommentWorkshopModel.exactComment(ref,new JSONArray().put(row)).getString("id").equals(row.getString("id")),"exact comment reference");
    JSONObject modified=SourceAnalysisPacket.copy(row);JSONArray changed=new JSONArray(row.getJSONArray("comments").toString());changed.getJSONObject(1).put("text","changed");modified.put("comments",changed);rejects(()->CommentWorkshopModel.exactComment(ref,new JSONArray().put(modified)));
    JSONObject fake=SourceAnalysisPacket.copy(row);JSONArray fakeComments=new JSONArray(row.getJSONArray("comments").toString());fakeComments.getJSONObject(2).put("creatorStatus","verified");fake.put("comments",fakeComments);
    rejects(()->CommentWorkshopModel.normalize(new JSONObject().put("schema","comment-workshop-v1").put("records",new JSONArray().put(fake)).toString()));
    JSONObject card=new JSONObject().put("id","manual-rule").put("kind","rules").put("title","人工卡片");check(!CommentWorkshopModel.assess(card).getBoolean("complete"),"incomplete rules remain draft");for(String key:CommentWorkshopModel.FIELDS)card.put(key,"人工填写");check(CommentWorkshopModel.assess(card).getString("status").equals("rule_complete_not_validated"),"complete rule must not claim validation");
    JSONObject nativeRow=new JSONObject().put("id","native").put("title","原稿").put("text",row.getString("content")).put("sourceUrl",row.getString("sourceUrl"));JSONObject binding=CommentWorkshopModel.bindSource(row,new JSONArray().put(nativeRow),new JSONArray());check(SourceAnalysisPacket.exactSource(binding,new JSONArray().put(nativeRow)).getString("id").equals("native"),"exact local source binding");rejects(()->CommentWorkshopModel.bindSource(row,new JSONArray().put(nativeRow).put(nativeRow),new JSONArray()));rejects(()->SourceAnalysisPacket.exactSource(binding,new JSONArray().put(SourceAnalysisPacket.copy(nativeRow).put("executionRevision","restored"))));
  }
  static void run(FlowInstrumentation f) throws Exception {
    model();f.check(true,"comment identity/coverage/parent/fulltext/unvalidated rule/exact source contracts");f.check(f.activity!=null&&f.activity.testing,"comment workshop requires isolated testing Activity");
    File file=new File(f.activity.getCacheDir(),"comment-workshop-"+UUID.randomUUID()+".sqlite");CommentWorkshopStore store=new CommentWorkshopStore(file);JSONObject preview=store.preview(fixture().toString());f.check(store.list("observations",0).length()==0,"preview makes no SQLite writes");f.check(store.merge(preview).getInt("added")==1&&store.merge(preview).getInt("duplicate")==1,"atomic idempotent comments import");
    JSONObject row=store.list("observations",0).getJSONObject(0);row=store.get("observations",row.getString("id"));JSONObject ref=CommentWorkshopModel.commentRef(row,"parent"),label=new JSONObject().put("kind","labels").put("id",CommentWorkshopModel.labelId(row.getString("id"),"parent")).put("label","support").put("sourceRef",ref);JSONObject saved=store.put(label,"");rejects(()->store.put(SourceAnalysisPacket.copy(label).put("label","counter"),""));f.check(store.labels(row.getString("id")).getString(saved.getString("id")).equals("support"),"manual classification persists; stale label refused");
    JSONObject card=store.put(new JSONObject().put("kind","rules").put("id","manual-card").put("title","人工规则草稿").put("entryRule","未保存规则草稿全文").put("sourceRef",ref),"");store.put(new JSONObject().put("kind","drafts").put("id","rule-draft").put("editingRuleId",card.getString("id")).put("editingRuleRevision",card.getString("recordRevision")).put("entryRule","未保存规则草稿全文").put("sourceRef",ref),"");
    CommentWorkshopStore reopened=new CommentWorkshopStore(file);f.check(reopened.get("rules",card.getString("id")).getString("entryRule").equals("未保存规则草稿全文"),"rule save/reopen full text");JSONObject archived=store.archiveRule(card.getString("id"),card.getString("recordRevision"));f.check(store.get("rules",card.getString("id")).length()==0&&store.restoreRule(archived.getString("id")).getString("entryRule").contains("全文"),"recoverable card removal/restoration leaves evidence intact");
    CommentWorkshopStore target=new CommentWorkshopStore(new File(f.activity.getCacheDir(),"comment-backup-"+UUID.randomUUID()+".sqlite"));f.check(target.merge(target.preview(new String(store.backup(),java.nio.charset.StandardCharsets.UTF_8))).getInt("added")==5,"complete backup comments/classification/card/draft/archive");
    f.ui(()->{try{CommentWorkshopScreen panel=new CommentWorkshopScreen(f.activity,f.activity.businessStore,file,null);f.check(panel.fields.get("entryRule").getText().toString().contains("全文"),"native rule draft restoration");panel.previewImport(fixture().toString());CommentWorkshopScreen recreated=new CommentWorkshopScreen(f.activity,f.activity.businessStore,file,null);f.check(recreated.pending.getJSONArray("rows").length()==1&&recreated.fields.get("entryRule").getText().toString().contains("全文"),"selected file preview and manual card draft survive recreation without merging");panel.setDarkTheme(true);panel.setDarkTheme(false);f.check(panel.fields.get("entryRule").getText().toString().contains("全文"),"theme preserves manual rule draft");recreated.showClassificationRecords();f.check(recreated.back()&&recreated.fields.get("entryRule").getText().toString().contains("全文"),"internal classification reader returns without losing card draft");}catch(Exception e){throw new RuntimeException(e);}});
  }
  public static void main(String[] args) throws Exception {model();if(args.length>0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0]),SourceAnalysisPacket.json(CommentWorkshopModel.normalize(fixture().toString()).getJSONObject(0)).getBytes(java.nio.charset.StandardCharsets.UTF_8));System.out.println("PASS comment workshop production Java identity/coverage/parent/fulltext/rule/exact-source model; no device/DB/network");}
}
